/**
 * Centralised env-var validation. Called once at boot from server.ts.
 *
 * Goal: refuse to start the production server if any critical secret is
 * missing or still set to a known-insecure default. Each var has a clear
 * human message so the operator can fix the deploy without reading the
 * source.
 *
 * Not in scope here:
 *  - JWT_SECRET / REFRESH_SECRET — those are guarded with FATAL throws in
 *    src/api/auth.ts (and again in admin.ts / bookings.ts / tenant.ts /
 *    pro-site.ts / site-settings.ts / test.ts) so the process exits before
 *    any route can be reached even if validateProductionEnv is skipped.
 *  - DB URL — defaulted to file:sqlite.db in src/db/index.ts; in prod the
 *    operator should set DATABASE_URL to a real libsql/Turso URL.
 *
 * Anything *only* used in dev (e.g. SMTP_*) is NOT enforced here.
 */

type EnvCheck = {
  /** Human-facing variable name for the error message. */
  name: string;
  /** Returns the value as present in process.env, or null when missing/blank. */
  read: () => string | null;
  /** When provided, the value is rejected if it matches (case-sensitive). */
  rejectIfEquals?: string[];
  /** When true, the check is skipped in non-production. */
  prodOnly?: boolean;
};

const checks: EnvCheck[] = [
  {
    name: 'CHAPA_SECRET_KEY',
    read: () => process.env.CHAPA_SECRET_KEY?.trim() || null,
    rejectIfEquals: ['CHASECK_TEST-g3pDAuHMdioBphvmSN0ETveYu5KPaDD5'],
    prodOnly: true,
  },
  {
    name: 'CHAPA_WEBHOOK_SECRET',
    read: () => process.env.CHAPA_WEBHOOK_SECRET?.trim() || null,
    rejectIfEquals: ['CyNDCzoXF7JsaPig6GErkdT0'],
    prodOnly: true,
  },
  {
    name: 'APP_URL',
    read: () => process.env.APP_URL?.trim() || null,
    prodOnly: true,
  },
  {
    name: 'JWT_SECRET',
    // Already FATAL-checked in the route modules; this is a second line of
    // defense that catches the "module not yet loaded" case.
    read: () => process.env.JWT_SECRET?.trim() || null,
    rejectIfEquals: ['supersecret_fallback', 'test-jwt-secret-'],
    prodOnly: true,
  },
  {
    name: 'REFRESH_SECRET',
    read: () => process.env.REFRESH_SECRET?.trim() || null,
    rejectIfEquals: ['supersecret_fallback', 'test-refresh-secret-'],
    prodOnly: true,
  },
];

export function validateProductionEnv(): void {
  const isProd = process.env.NODE_ENV === 'production';
  const failures: string[] = [];

  for (const c of checks) {
    if (c.prodOnly && !isProd) continue;
    const value = c.read();
    if (!value) {
      failures.push(`${c.name} is not set`);
      continue;
    }
    if (c.rejectIfEquals && c.rejectIfEquals.includes(value)) {
      failures.push(`${c.name} is set to a known-insecure default (rotate it)`);
    }
  }

  if (failures.length > 0) {
    // Throw a single error with all problems listed so the operator fixes
    // them in one pass instead of redeploying for each missing var.
    throw new Error(
      `[env] Production boot aborted. Fix the following:\n  - ${failures.join('\n  - ')}`,
    );
  }
}
