let purifyInstance: any = null;

async function getDOMPurify() {
  if (purifyInstance) return purifyInstance;

  const createDOMPurify = (await import('dompurify')).default;

  if (typeof window !== 'undefined' && typeof document !== 'undefined') {
    purifyInstance = createDOMPurify(window as any);
  } else {
    const { JSDOM } = await import('jsdom');
    purifyInstance = createDOMPurify(new JSDOM('').window as any);
  }

  const EgebeyaWidgetOrigin = 'https://api.egebeya.et/';

  purifyInstance.addHook('uponSanitizeAttribute', (node: any, data: any) => {
    if (node.tagName?.toLowerCase() !== 'iframe') return;
    if (data.attrName !== 'src') return;
    const value = (data.attrValue || '').trim();
    if (value === '') {
      data.keepAttr = false;
      return;
    }
    if (!value.startsWith(EgebeyaWidgetOrigin)) {
      data.keepAttr = false;
      return;
    }
  });

  return purifyInstance;
}

const IframeAttrs = [
  'src', 'width', 'height', 'frameborder', 'allow', 'allowfullscreen', 'title', 'loading',
];

const AllowedTags = [
  'iframe', 'html', 'head', 'body', 'title', 'meta', 'link', 'style',
  'div', 'span', 'header', 'footer', 'nav', 'main', 'section', 'article', 'aside',
  'h1', 'h2', 'h3', 'h4', 'h5', 'h6', 'p', 'br', 'hr', 'ul', 'ol', 'li',
  'img', 'a', 'figure', 'figcaption', 'picture', 'source', 'video', 'audio',
  'table', 'thead', 'tbody', 'tfoot', 'tr', 'th', 'td',
  'form', 'label', 'input', 'button', 'textarea', 'select', 'option',
  'blockquote', 'pre', 'code',
];

export async function sanitizePublishedCode(rawHtml: string): Promise<string> {
  const DOMPurify = await getDOMPurify();
  const input = rawHtml ?? '';

  return DOMPurify.sanitize(input, {
    ALLOWED_TAGS: AllowedTags,
    ALLOWED_ATTR: [
      ...IframeAttrs,
      'class', 'id', 'style', 'href', 'rel', 'target', 'alt', 'title',
      'name', 'content', 'charset', 'srcset', 'sizes', 'width', 'height',
      'type', 'placeholder', 'value', 'required', 'disabled', 'checked', 'selected',
      'for', 'colspan', 'rowspan', 'controls', 'autoplay', 'loop', 'muted',
      'preload', 'poster', 'crossorigin', 'loading', 'decoding',
      'role', 'aria-label', 'aria-labelledby', 'aria-describedby',
      'aria-hidden', 'aria-expanded', 'aria-controls', 'data-business-id',
    ],
    FORBID_ATTR: [],
    ALLOW_DATA_ATTR: false,
  });
}
