import { NextFunction, Request, Response } from 'express';
import jwt from 'jsonwebtoken';
import { db } from '../../db';
import { users } from '../../db/schema';
import { eq } from 'drizzle-orm';

// Centralised secret accessors. The process MUST refuse to start in
// production with a missing/known-default secret (enforced at boot by
// envGuards.ts); the non-production fallbacks keep the test suite working
// without configuration while never being used in production.
export function jwtSecret(): string {
  const s = process.env.JWT_SECRET;
  if (!s) {
    if (process.env.NODE_ENV === 'production') {
      throw new Error('FATAL: JWT_SECRET is not set. Refusing to start in production.');
    }
    return 'supersecret_fallback';
  }
  return s;
}

export function refreshSecret(): string {
  const s = process.env.REFRESH_SECRET;
  if (!s) {
    if (process.env.NODE_ENV === 'production') {
      throw new Error('FATAL: REFRESH_SECRET is not set. Refusing to start in production.');
    }
    return 'refresh_supersecret_fallback';
  }
  return s;
}

export interface AuthOptions {
  /** Restrict to these roles (e.g. ['owner']). Omit to allow any authenticated role. */
  roles?: string[];
}

/**
 * Authenticate a Bearer access token and verify the caller's `tokenVersion`
 * against the users table so that logout / password changes revoke previously
 * issued access tokens immediately (not only after the 15-minute JWT expiry).
 *
 * The resolved JWT payload is attached to `req.user` for downstream handlers.
 */
export function requireAuth(options: AuthOptions = {}) {
  return async (req: Request, res: Response, next: NextFunction) => {
    const authHeader = req.headers.authorization;
    if (!authHeader?.startsWith('Bearer ')) {
      return res.status(401).json({ error: 'Unauthorized' });
    }
    const token = authHeader.slice(7);

    let payload: any;
    try {
      payload = jwt.verify(token, jwtSecret());
    } catch {
      return res.status(401).json({ error: 'Invalid token' });
    }

    if (!payload?.userId) {
      return res.status(401).json({ error: 'Invalid token' });
    }

    const user = await db.select().from(users).where(eq(users.id, payload.userId)).get();
    if (!user) {
      return res.status(401).json({ error: 'User not found' });
    }

    const currentVersion = (user as any).tokenVersion ?? 0;
    if (typeof payload.tokenVersion !== 'number' || payload.tokenVersion !== currentVersion) {
      return res.status(401).json({ error: 'Session has been revoked, please sign in again' });
    }

    if (options.roles && options.roles.length > 0 && !options.roles.includes(payload.role)) {
      return res.status(403).json({ error: 'Forbidden' });
    }

    (req as any).user = payload;
    next();
  };
}
