import 'dotenv/config';
import express from 'express';
import cors from 'cors';
import helmet from 'helmet';
import multer from 'multer';
import path from 'path';
import { createServer as createViteServer } from 'vite';
import apiRoutes from './src/api';
import { ensureSchemaMigrations } from './src/db/migrations';
import { validateProductionEnv } from './src/lib/envGuards';

const app = express();
const PORT = 3000;

// Security headers. CSP stays disabled for the Sandpack/Puck editor (it needs
// unsafe-inline/eval); the sandboxed preview iframe confines tenant code and a
// Strict CSP is applied on any future published-code serving path.
app.use(helmet({ contentSecurityPolicy: false }));

// CORS restricted to the platform + tenant subdomains + local dev origins.
// The old `cors()` default allowed any origin against the whole API.
const allowedOrigin = (origin: string | undefined): boolean => {
  if (!origin) return true; // same-origin, non-browser, curl, webhooks
  let host: string;
  try {
    host = new URL(origin).hostname;
  } catch {
    return false;
  }
  return (
    host === 'localhost' ||
    host === '127.0.0.1' ||
    host === 'egebeya.et' ||
    host.endsWith('.egebeya.et') ||
    host.endsWith('.run.app')
  );
};
app.use(cors({ origin: allowedOrigin }));

// Capture the raw request body buffer so the Chapa webhook can HMAC-verify the
// exact bytes the provider signed (JSON.stringify re-serialisation would
// reorder keys and break verification).
app.use(express.json({
  verify: (req: any, _res, buf) => {
    req.rawBody = buf;
  },
}));

// API Routes
app.use('/api', apiRoutes);

// Block serving sensitive project files in dev (Vite otherwise happily serves
// sqlite.db, source, and configs from the project root). Applies to the
// dev/static file-serving layers, not to API routes.
const BLOCKED_FILE = /\.(env|db|sqlite|sqlite3|log|lock|cjs)$/i;
const BLOCKED_PATHS = /^\/(\.git|\.env|sqlite\.db|server\.ts|server\.cjs|tsconfig\.json|package\.json|package-lock\.json|bun\.lock|drizzle\.config\.ts|metadata\.json|_secrets_audit\.mjs|_check_tables\.)/i;
app.use((req, res, next) => {
  if (BLOCKED_FILE.test(req.path) || BLOCKED_PATHS.test(req.path)) {
    return res.status(403).json({ error: 'Forbidden' });
  }
  next();
});

// Global JSON error handler — registered LAST so thrown errors (malformed
// JSON, multer rejections, unexpected 500s) become JSON with a generic
// message, never Express's default HTML stack trace that leaks filesystem
// paths. Full detail is logged server-side only.
app.use((err: any, _req: any, res: any, _next: any) => {
  if (err instanceof multer.MulterError || err?.message === 'Invalid file type' || err?.message === 'Only images are allowed') {
    return res.status(400).json({ error: 'Invalid upload. Please upload a valid image file.' });
  }
  if (err?.type === 'entity.parse.failed' || err instanceof SyntaxError) {
    return res.status(400).json({ error: 'Invalid JSON payload.' });
  }
  console.error('[error]', err);
  res.status(500).json({ error: 'An internal server error occurred.' });
});

async function startServer() {
  // Refuse to boot in production with missing/known-insecure env secrets.
  if (process.env.NODE_ENV === 'production') {
    validateProductionEnv();
  }

  // Apply schema migrations on every boot so a fresh deploy gains columns and
  // tables (token_version, is_suspended, security_events, site_config, …).
  try {
    const added = await ensureSchemaMigrations();
    if (Object.keys(added).length > 0) {
      console.log('[migrations] applied:', JSON.stringify(added));
    }
  } catch (migrateErr) {
    console.error('[migrations] failed:', migrateErr);
  }

  const uploadsPath = path.join(process.cwd(), 'dist', 'uploads');
  app.use('/uploads', express.static(uploadsPath));

  if (process.env.NODE_ENV !== 'production') {
    const vite = await createViteServer({
      server: { middlewareMode: true },
      appType: 'spa',
    });
    app.use(vite.middlewares);
  } else {
    const distPath = path.join(process.cwd(), 'dist');
    app.use('/uploads', express.static(path.join(distPath, 'uploads')));
    // Only public assets live under dist (the server bundle is built to
    // dist-server/ so dist/server.cjs is never downloadable).
    app.use(express.static(distPath));
    app.get('*splat', (req, res) => {
      res.sendFile(path.join(distPath, 'index.html'));
    });
  }

  app.listen(PORT, '0.0.0.0', () => {
    console.log(`Server running on http://localhost:${PORT}`);
  });
}

startServer();
